from django.db import migrations, models
from django.utils.text import slugify


def fill_empty_slugs(apps, schema_editor):
    """Курсам із порожнім slug генеруємо унікальний slug з назви."""
    Course = apps.get_model("courses", "Course")
    for course in Course.objects.filter(slug=""):
        base = slugify(course.title)[:40] or "course"
        slug, n = base, 2
        while Course.objects.filter(slug=slug).exists():
            slug, n = f"{base}-{n}", n + 1
        course.slug = slug
        course.save(update_fields=["slug"])


